    "materia": "Língua Portuguesa",
    "assunto": "Semântica e Significação das Palavras",
    "enunciado": "Oscar 2026: mudança de regra exige que votantes assistam a todos os filmes indicados A Academia anunciou uma nova regra para o Oscar 2026, nesta segunda-feira (21). A partir de agora, para que os membros se tornem aptos a votar, será necessário assistir a todos os filmes da categoria, algo que não era obrigatório antes. \"Em uma mudança de procedimento, os membros da Academia agora devem assistir a todos os filmes indicados em cada categoria para serem elegíveis para votar na rodada final do Oscar. Todos os indicados designados também serão incluídos na votação final\", informou a organização. De acordo com a revista \"Variety\", a Academia vai monitorar a atividade de visualização por meio de sua plataforma de streaming exclusiva para membros, a Academy Screening Room. Caso os votantes assistam aos longas em festivais, exibições ou eventos privados, será necessário enviar um formulário para comprovação. Na época da premiação deste ano, fontes anônimas votantes revelaram a revistas como \"Variety\" e \"Entertainment Weekly\" que não assistiram a todas as obras indicadas nas respectivas categorias que votavam. Entre os filmes mencionados estava o brasileiro \"Ainda Estou Aqui\", nomeado a três categorias e vencedor de Melhor Filme Internacional. A 98ª edição do Oscar, cuja cerimônia acontecerá em 15 de março de 2026, também teve mudanças quanto a filmes que usam inteligência artificial e outras ferramentas digitais. O uso de IA não contribui nem prejudica as chances de obter uma indicação, mas a produção será julgada levando em consideração o grau em que um ser humano esteve no centro da autoria criativa. Dependendo, isto pode ter impacto sobre qual filme será premiado. Fonte: “De acordo com a revista ‘Variety’, a Academia vai monitorar a atividade de visualização por meio de sua plataforma de streaming exclusiva para membros, a Academy Screening Room” (3º parágrafo). O termo em destaque poderia ser substituído, sem alteração de sentido, por:",
