    "enunciado": "Leia o texto a seguir: O GATO QUE TINHA VISÕES Fábula americana (Arnold Lobel, 1933-1987) – Eu tive uma visão maravilhosa – disse o gato para a vara de pescar enquanto caminhava até o rio. – Vi um peixe enorme e gordo num prato de porcelana, e ele nadava num molho de manteiga derretida e suco de limão. Então ele colocou uma minhoca no anzol, jogou-o na água e sentou-se enquanto esperava o peixe morder. Depois de uma hora o gato disse: – Eu tive uma visão. Vi um peixe num prato de porcelana, e ele estava coberto de manteiga derretida com suco de limão. Muitas horas depois o gato disse: – Ainda tenho uma visão. Vejo um peixinho num prato de porcelana com algumas gotas de manteiga derretida e suco de limão. Finalmente o gato disse: – A visão mudou. Agora não vejo peixe nem manteiga derretida ou suco de limão. Tudo o que vejo é um prato de porcelana tão vazio quanto o meu estômago. O gato estava para desistir de pescar quando sentiu alguma coisa puxando sua linha. Um minuto depois ele tirou da água um peixe enorme e gordo. Então ele correu para casa e o fritou, colocando-o em seguida num prato de porcelana, que encheu de manteiga derretida e suco de limão. – Que refeição maravilhosa! exclamou ele. Fonte: ALEX, Ben. Fábulas do mundo todo: Esopo, Leonardo da Vinci, Andersen, Tolstoi e muitos outros. Melhoramentos, 1899. A expressão “prato de porcelana” significa que o prato foi fabricado a partir do seguinte material:",
