    "cargo": "Cargos Diversos (Superior/Médio)",
    "materia": "Língua Portuguesa",
    "assunto": "Semântica e Significação das Palavras",
    "enunciado": "\"Na medida do possível\" Nada mais elegante que dizer \"na medida do possível\". Que sería de nós sem a medida do possível? Sem a sensatez do senso de medida? Nada melhor do que viver - viver na medida do possível. \"Você me ama?\" \"Na medida do possível\". \"Você é honesto?\" \"Na medida do possível.\" \"Você quer viver eternamente?\" \"Na medida do possível\". \"Você está me dando o fora?\" \"Na medida do possível\". Falando agora mais a sério, essa expressão é também um Indice da maturidade modesta: pode indicar o cuidado realista de quem prefere não exagerar em nada e contar com os imprevistos, com os grandes obstáculos que surgem inopinadamente. Ela será mais comumente utilizada por adultos, por pessoas já experientes; dificil imaginar jovens dizendo \"na medida do possível\", quando a tendência deles é contar com medidas radicais. Entre as correntes filosóficas, talvez a do estoicismo seja a que melhor absorva a força dessa expressão. Um estoico não desafia as forças do destino: ele as respeita e conta sempre com a possibilidade de deparar com um desafio invencível, diante do qual ele manterá uma reação sóbria de quem resiste, sim, mas na medida do possível. Na linguagem comum, um estoico seria aquele que se recusa a dar murro em ponta de faca. Ele buscará se conter, na medida do possível. (Alcino Martinez, a editar) Considerando o contexto, traduz-se adequadamente o sentido de uma expressão do texto em:",
