    "materia": "Língua Portuguesa",
    "assunto": "Semântica e Significação das Palavras",
    "enunciado": "(Engenharia Civil) “Que menino especula!” Eu era um menino muito perguntador, como quase todas as crianças, e volta e meia tinha que ouvir de um adulto: Mas você é especula, hein? E eu via logo que ser um menino “especula” não devia ser muito bonito. Nem por isso guardava minhas armas de perguntador: continuava a especular sobre tudo o que não entendia. Eu ainda não conhecia a réplica justa a quem me acusasse de especula: - Mas perguntar não ofende. Mais tarde tive a minha vingança. Aprendi que especular é investigar, pesquisar, refletir... Aprendi mais: que os homens muito curiosos, de muito antigamente, olhavam os astros no céu pra ver se entendiam a formação de suas andanças no espaço, seus movimentos regulares. Não contando ainda com a sofisticação de telescópios, valiam-se os antigos de um espelho, um “speculum”, que fixavam no chão apontado para o alto. Na superficie plana do espelho refletiam-se os astros iluminados no céu, e nela os astronomos pioneiros iam marcando a posição e os movimentos dos corpos celestes. Era isso o que também se entendia por especular: observar algo por meio do reflexo de um espelho. Os primeiros astrónomos foram grandes especulas. Com o tempo, especulação passou a designar um processo mental abstrato, que formula hipóteses e elabora ideias. Pensamento especulativo, para muitos, é o principio mesmo d inquirição filosófica, Portanto, fui mesmo, e com muita honra, um menino especula, sim senhor. Como quase todas as crianças, estava interessado em saber quanta coisa havia entre o céu e a terra que ia além da nossa filosofia, ou dos nossos olhos terrestres. Da minha maneira, acionava o espelho da minha curiosidade para saber mais coisas dos astros do céu, o tempo cósmico, do destino das esferas - coisas que mesmo um telescópio espacial está longe de conseguir esclarecer, para poder satisfazer os eternos meninos especulas. (Alcebiades Vilanova, a ecitar) No contexto dado, há emprego de uma expressão com sentido conotativo na frase:",
