    "assunto": "Semântica e Significação das Palavras",
    "enunciado": "Significação Contextual de Palavras e Expressões. Sinônimos e Antônimos. Administrativa Quando abri os olhos, vi o vulto de uma mulher e o de uma criança. As duas figuras estavam inertes diante de mim, e a claridade indecisa da manhã nublada devolvia os dois corpos ao sono e ao cansaço de uma noite maldormida. Sem perceber, tinha me afastado do lugar escolhido para dormir e ingressado numa espécie de gruta vegetal, entre o globo de luz e o caramanchão que dá acesso aos fundos da casa. Deitada na grama, com o corpo encolhido por causa do sereno, sentia na pele a roupa úmida e tinha as mãos repousadas nas páginas também úmidas de um caderno aberto, onde rabiscara, meio sonolenta, algumas impressões do voo noturno. Lembro que adormecera observando o perfil da casa fechada e quase deserta, tentando visualizar os dois leões de pedra entre as mangueiras perfiladas no outro lado da rua. A mulher se aproximou de mim e. sem dizer uma palavra, afastou com o pé uma boneca de pano que estava entre o alfoje e o meu rosto; depois continuou imóvel, com o olhar perdido na escuridão da gruta, enquanto a criança apanhava o corpo de pano e, correndo em zigue-zague, alcançava o interior da casa. Eu procurava reconhecer o rosto daquela mulher. Talvez em algum lugar da infância tivesse convivido com ela, mas não encontrei nenhum traço familiar, nenhum sinal que acenasse ao passado. (Adaptado de HATOUM, Milton. Relato de um certo Oriente. São Paulo: Companhia das Letras, 2008) No trecho As duas figuras estavam inertes diante de mim, o termo “inertes” pode ser substituído, sem alterar o sentido da frase, por:",
