        "id": "D",
        "texto": "Verdade seja escrita: a tarefa se tornava dia a dia mais fácil, Era só imaginar cores e sonos e os olhos já ficavam cansados. Entretanto, bastava ligar o aparelho e os dois já calam no sono,"
