    "assunto": "Semântica e Significação das Palavras",
    "enunciado": "Estatuto do Amor gravidade indizível de tua infâmia. Para saberes que gozo terias sentido se, em vez de matá-la, a tivesses levado ao peito enquanto vivia. O único capaz de projetar luz sobre esta precária existência humana. maltratar, como se te coubesse este desapiedado e falso exercício da justiça. da maldade. Nenhum pedaço de carne humana merece ser golpeado pela indiferença, pela violência, pela injustiça. Portanto, não abatas a tiro, a tapas, a arranhões, o corpo da mulher. quer que esteja no recinto sagrado do lar é, ao mesmo tempo, o sucessor do teu horror e da lua capacidade de maravilharse. o espelho de tua irrenunciável humanidade. (Adaptado de: PIÑON, Nélida. Uma furtiva lágrima. Rio de Janeiro: Record, 2019. pp. 15-18) Não lhe negues, então, o olhar compassivo, as lágrimas conspurcadas por uma realidade que traiu teus sonhos. Quem quer que esteja no recinto sagrado do lar é, ao mesmo tempo, o sucessor do teu horror e da tua capacidade de maravilhar-se. (6º parágrafo) No trecho acima",
